function validate([s, k]) {
  if (!Number.isInteger(k) || k < 2 || k > 2000) return 'k is an integer from 2 to 2000.';
  if (typeof s !== 'string' || !/^[a-z]*$/.test(s)) return 's uses only lowercase English letters.';
  if (s.length < 2 || s.length > 2000) return 's has 2 to 2000 characters.';
  if (s.length >= 8 * k) return 's must be shorter than 8 * k characters.';
  return null;
}

