function longestSubsequenceRepeatedK(s, k) {
  const count = new Array(26).fill(0);
  for (const ch of s) {
    count[ch.charCodeAt(0) - 97]++;
  }
  const letters = [];
  for (let i = 0; i < 26; i++) {
    if (count[i] >= k) {
      letters.push(String.fromCharCode(97 + i));
    }
  }

  const isRepeated = (seq) => {
    let j = 0;
    let repeats = 0;
    for (const ch of s) {
      if (ch !== seq[j]) continue;
      j++;
      if (j === seq.length) {
        j = 0;
        repeats++;
        if (repeats === k) return true;
      }
    }
    return false;
  };

  let best = '';
  let level = [''];
  while (level.length > 0) {
    const next = [];
    for (const prefix of level) {
      for (const letter of letters) {
        const candidate = prefix + letter;
        if (isRepeated(candidate)) {
          next.push(candidate);
          best = candidate;
        }
      }
    }
    level = next;
  }
  return best;
}

