function longestSubsequenceRepeatedK(s, k) {
  const isSubsequence = (t) => {
    let i = 0;
    for (const ch of s) if (i < t.length && ch === t[i]) i++;
    return i === t.length;
  };
  // Try every string over the letters of s up to length n / k.
  const alphabet = [...new Set(s)].sort();
  const maxLength = Math.floor(s.length / k);
  let best = '';
  const visit = (seq) => {
    if ((seq.length > best.length || (seq.length === best.length && seq > best)) && isSubsequence(seq.repeat(k))) best = seq;
    if (seq.length === maxLength) return;
    for (const c of alphabet) visit(seq + c);
  };
  visit('');
  return best;
}

