function generate(rand, size) {
  const pick = (alphabet) => alphabet[Math.floor(rand() * alphabet.length)];
  if (size !== 'large') {
    const k = 2 + Math.floor(rand() * 3);
    const n = 2 + Math.floor(rand() * (Math.min(14, 8 * k - 1) - 1));
    const alphabet = 'abcd'.slice(0, 1 + Math.floor(rand() * 4));
    let s = '';
    for (let i = 0; i < n; i++) s += pick(alphabet);
    return [s, k];
  }
  // Plant a pattern repeated k times, then scatter random letters through it.
  const length = 1 + Math.floor(rand() * 7);
  const k = 200 + Math.floor(rand() * (Math.floor(1800 / length) - 200));
  const n = Math.min(2000, 8 * k - 1);
  const pool = 'abcdefghijklmnopqrstuvwxyz'.slice(0, 3 + Math.floor(rand() * 24));
  let pattern = '';
  for (let i = 0; i < length; i++) pattern += pick(pool);
  const chars = pattern.repeat(k).split('');
  while (chars.length < n) chars.splice(Math.floor(rand() * (chars.length + 1)), 0, pick(pool));
  return [chars.join(''), k];
}
